"""Página inicial — OTHIL Relatórios Comerciais."""
import datetime
import json
import os
import streamlit as st

_LOGO_B64 = ""

_GER_DIR  = os.path.join(os.path.dirname(__file__), '..', 'gerencia_data')
_OT_META  = os.path.join(_GER_DIR, 'ontrack_publicado.json')
_OT_CLI   = os.path.join(_GER_DIR, 'ontrack_clientes_publicado.json')

hoje      = datetime.date.today()
agora     = datetime.datetime.now()
dias_pt   = ["Segunda-feira","Terça-feira","Quarta-feira","Quinta-feira",
             "Sexta-feira","Sábado","Domingo"]
meses_pt  = ["janeiro","fevereiro","março","abril","maio","junho",
             "julho","agosto","setembro","outubro","novembro","dezembro"]
data_fmt  = dias_pt[hoje.weekday()] + ", " + str(hoje.day) + " de " + meses_pt[hoje.month-1] + " de " + str(hoje.year)


def _tempo_desde(iso_str):
    try:
        dt = datetime.datetime.fromisoformat(iso_str)
        mins = int((agora - dt).total_seconds() // 60)
        if mins < 1:
            return "agora mesmo"
        if mins < 60:
            return "há " + str(mins) + " min"
        horas = mins // 60
        if horas < 24:
            return "há " + str(horas) + "h"
        dias = horas // 24
        return "há " + str(dias) + " dia" + ("s" if dias > 1 else "")
    except Exception:
        return "—"


def _status_modulo(json_path):
    if not os.path.exists(json_path):
        return "⚪", "Sem dados", "#aaa"
    try:
        with open(json_path, encoding="utf-8") as f:
            d = json.load(f)
        tempo = _tempo_desde(d.get("publicado_em", ""))
        return "🟢", tempo, "#2D6A4F"
    except Exception:
        return "🔴", "Erro ao ler", "#c00"


